import RuntimeABI

extension KIRLoweringDriver {
    /// Synthesizes KIR functions and synthetic builder nominal types/methods
    /// generated by `LombokPlugin` (`org.jetbrains.kotlin.lombok`).
    func synthesizeLombokMembers(
        classDecl: ClassDecl,
        classSymbol: SymbolID,
        shared: KIRLoweringSharedContext
    ) -> (classMemberDecls: [KIRDeclID], moduleExtraDecls: [KIRDeclID]) {
        guard let info = shared.sema.lombokClasses[classSymbol] else {
            return ([], [])
        }
        let sema = shared.sema
        let arena = shared.arena
        var classMemberDecls: [KIRDeclID] = []
        var moduleExtraDecls: [KIRDeclID] = []
        var companionMethodDecls: [KIRDeclID] = []

        for methodSym in info.methodSymbols {
            guard arena.function(for: methodSym) == nil,
                  let kind = sema.lombokMethods[methodSym]
            else { continue }
            guard let declID = synthesizeLombokMethod(symbol: methodSym, kind: kind, shared: shared) else {
                continue
            }
            if sema.symbols.parentSymbol(for: methodSym) == classSymbol {
                classMemberDecls.append(declID)
            } else if let compID = info.companionSymbol,
                      sema.symbols.parentSymbol(for: methodSym) == compID
            {
                companionMethodDecls.append(declID)
                moduleExtraDecls.append(declID)
            } else {
                moduleExtraDecls.append(declID)
            }
        }

        // If Lombok synthesized a companion object not present in AST, emit its
        // nominal type and singleton global so static factories / builder() resolve.
        if let compID = info.companionSymbol, classDecl.companionObject == nil {
            let compType = sema.types.make(.classType(ClassType(
                classSymbol: compID,
                args: [],
                nullability: .nonNull
            )))
            moduleExtraDecls.append(arena.appendDecl(.global(KIRGlobal(symbol: compID, type: compType))))
            moduleExtraDecls.append(arena.appendDecl(.nominalType(KIRNominalType(
                symbol: compID,
                memberDecls: companionMethodDecls
            ))))
        }

        if let builderInfo = info.builderInfo {
            let builderDecls = synthesizeLombokBuilderDecls(builderInfo: builderInfo, shared: shared)
            moduleExtraDecls.append(contentsOf: builderDecls)
        }

        return (classMemberDecls, moduleExtraDecls)
    }

    private func synthesizeLombokBuilderDecls(
        builderInfo: LombokBuilderClassInfo,
        shared: KIRLoweringSharedContext
    ) -> [KIRDeclID] {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        var memberDecls: [KIRDeclID] = []
        var extraDecls: [KIRDeclID] = []

        // 1. Parameterless constructor for <Class>Builder
        let ctorSym = builderInfo.constructorSymbol
        if arena.function(for: ctorSym) == nil,
           let signature = sema.symbols.functionSignature(for: ctorSym)
        {
            let receiverType = signature.receiverType ?? sema.types.anyType
            let selfParamSym = makeLombokReceiverParam(
                ownerFQName: sema.symbols.symbol(ctorSym)?.fqName ?? [],
                shared: shared
            )
            let selfRef = arena.appendExpr(.symbolRef(selfParamSym), type: receiverType)
            let ctorFunc = KIRFunction(
                symbol: ctorSym,
                name: interner.intern("<init>"),
                params: [KIRParameter(symbol: selfParamSym, type: receiverType)],
                returnType: receiverType,
                body: [
                    .constValue(result: selfRef, value: .symbolRef(selfParamSym)),
                    .returnValue(selfRef),
                ],
                isSuspend: false,
                isInline: false
            )
            let declID = arena.appendDecl(.function(ctorFunc))
            extraDecls.append(declID)
        }

        // 2. Fluent setter methods
        for setterSym in builderInfo.setterMethods {
            guard arena.function(for: setterSym) == nil,
                  let kind = sema.lombokMethods[setterSym],
                  let declID = synthesizeLombokMethod(symbol: setterSym, kind: kind, shared: shared)
            else { continue }
            memberDecls.append(declID)
            extraDecls.append(declID)
        }

        // 3. build() method
        if arena.function(for: builderInfo.buildMethod) == nil,
           let kind = sema.lombokMethods[builderInfo.buildMethod],
           let declID = synthesizeLombokMethod(symbol: builderInfo.buildMethod, kind: kind, shared: shared)
        {
            memberDecls.append(declID)
            extraDecls.append(declID)
        }

        let nominalDecl = arena.appendDecl(.nominalType(KIRNominalType(
            symbol: builderInfo.builderClassSymbol,
            memberDecls: memberDecls
        )))
        extraDecls.append(nominalDecl)
        return extraDecls
    }

    private func synthesizeLombokMethod(
        symbol: SymbolID,
        kind: LombokSynthesizedMethodKind,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        guard let symInfo = sema.symbols.symbol(symbol),
              let signature = sema.symbols.functionSignature(for: symbol)
        else { return nil }

        switch kind {
        case let .getter(ownerClass, propertySymbol):
            return emitLombokGetter(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                propertySymbol: propertySymbol,
                signature: signature,
                shared: shared
            )
        case let .setter(ownerClass, propertySymbol, returnsSelf):
            return emitLombokSetter(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                propertySymbol: propertySymbol,
                returnsSelf: returnsSelf,
                signature: signature,
                shared: shared
            )
        case let .with(ownerClass, propertySymbol):
            return emitLombokWith(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                propertySymbol: propertySymbol,
                signature: signature,
                shared: shared
            )
        case let .toStringMethod(ownerClass, properties, includeFieldNames):
            return emitLombokToString(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                properties: properties,
                includeFieldNames: includeFieldNames,
                signature: signature,
                shared: shared
            )
        case let .equalsMethod(ownerClass, properties):
            return emitLombokEquals(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                properties: properties,
                signature: signature,
                shared: shared
            )
        case let .hashCodeMethod(ownerClass, properties):
            return emitLombokHashCode(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: ownerClass,
                properties: properties,
                signature: signature,
                shared: shared
            )
        case let .staticConstructorFactory(targetClass, constructorSymbol):
            return emitLombokFactoryCall(
                methodSymbol: symbol,
                name: symInfo.name,
                targetClass: targetClass,
                constructorSymbol: constructorSymbol,
                signature: signature,
                shared: shared
            )
        case let .builderFactoryMethod(builderClass, builderConstructor):
            return emitLombokFactoryCall(
                methodSymbol: symbol,
                name: symInfo.name,
                targetClass: builderClass,
                constructorSymbol: builderConstructor,
                signature: signature,
                shared: shared
            )
        case let .builderSetter(builderClass, propertySymbol):
            return emitLombokSetter(
                methodSymbol: symbol,
                name: symInfo.name,
                ownerClass: builderClass,
                propertySymbol: propertySymbol,
                returnsSelf: true,
                signature: signature,
                shared: shared
            )
        case let .builderBuildMethod(targetClass, builderClass, fieldPairs):
            return emitLombokBuilderBuild(
                methodSymbol: symbol,
                name: symInfo.name,
                targetClass: targetClass,
                builderClass: builderClass,
                fieldPairs: fieldPairs,
                signature: signature,
                shared: shared
            )
        }
    }

    // MARK: - Method Emitters

    private func emitLombokGetter(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        propertySymbol: SymbolID,
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)
        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]

        if let offset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propertySymbol, sema: sema) {
            let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: sema.types.intType)
            body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))
            let resultExpr = arena.appendTemporary(type: signature.returnType)
            body.append(.call(
                callee: interner.intern("kk_array_get_inbounds"),
                arguments: [selfRef, offsetExpr],
                result: resultExpr,
                canThrow: false
            ))
            body.append(.returnValue(resultExpr))
        } else {
            let zeroExpr = arena.appendExpr(.intLiteral(0), type: signature.returnType)
            body.append(.constValue(result: zeroExpr, value: .intLiteral(0)))
            body.append(.returnValue(zeroExpr))
        }

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: [KIRParameter(symbol: selfParam, type: receiverType)],
            returnType: signature.returnType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokSetter(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        propertySymbol: SymbolID,
        returnsSelf: Bool,
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)

        var params = [KIRParameter(symbol: selfParam, type: receiverType)]
        for (idx, paramType) in signature.parameterTypes.enumerated() {
            let pSym = signature.valueParameterSymbols.indices.contains(idx)
                ? signature.valueParameterSymbols[idx]
                : methodSymbol
            params.append(KIRParameter(symbol: pSym, type: paramType))
        }

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]
        if params.count >= 2,
           let offset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propertySymbol, sema: sema)
        {
            let valueParam = params[1]
            let valueRef = arena.appendExpr(.symbolRef(valueParam.symbol), type: valueParam.type)
            body.append(.constValue(result: valueRef, value: .symbolRef(valueParam.symbol)))
            let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: sema.types.intType)
            body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))
            let unusedResult = arena.appendTemporary(type: sema.types.anyType)
            body.append(.call(
                callee: interner.intern("kk_array_set"),
                arguments: [selfRef, offsetExpr, valueRef],
                result: unusedResult,
                canThrow: false
            ))
        }
        if returnsSelf {
            body.append(.returnValue(selfRef))
        } else {
            body.append(.returnUnit)
        }

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: params,
            returnType: signature.returnType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokWith(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        propertySymbol: SymbolID,
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)
        var params = [KIRParameter(symbol: selfParam, type: receiverType)]
        for (idx, paramType) in signature.parameterTypes.enumerated() {
            let pSym = signature.valueParameterSymbols.indices.contains(idx)
                ? signature.valueParameterSymbols[idx]
                : methodSymbol
            params.append(KIRParameter(symbol: pSym, type: paramType))
        }

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]
        let newObj = emitAllocateLombokInstance(
            ownerSymbol: ownerClass,
            resultType: signature.returnType,
            sema: sema,
            arena: arena,
            interner: interner,
            instructions: &body
        )

        if let layout = sema.symbols.nominalLayout(for: ownerClass) {
            let targetOffset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propertySymbol, sema: sema)
            let uniqueOffsets = Set(layout.fieldOffsets.values).sorted()
            for offset in uniqueOffsets {
                let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: sema.types.intType)
                body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))
                let valueToStore: KIRExprID
                if offset == targetOffset, params.count >= 2 {
                    let valueParam = params[1]
                    let vRef = arena.appendExpr(.symbolRef(valueParam.symbol), type: valueParam.type)
                    body.append(.constValue(result: vRef, value: .symbolRef(valueParam.symbol)))
                    valueToStore = vRef
                } else {
                    let readVal = arena.appendTemporary(type: sema.types.anyType)
                    body.append(.call(
                        callee: interner.intern("kk_array_get_inbounds"),
                        arguments: [selfRef, offsetExpr],
                        result: readVal,
                        canThrow: false
                    ))
                    valueToStore = readVal
                }
                let setRes = arena.appendTemporary(type: sema.types.anyType)
                body.append(.call(
                    callee: interner.intern("kk_array_set"),
                    arguments: [newObj, offsetExpr, valueToStore],
                    result: setRes,
                    canThrow: false
                ))
            }
        }
        body.append(.returnValue(newObj))

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: params,
            returnType: signature.returnType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokToString(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        properties: [SymbolID],
        includeFieldNames: Bool,
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let stringType = sema.types.stringType
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)
        let ownerName = sema.symbols.symbol(ownerClass).map { interner.resolve($0.name) } ?? "Object"

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]
        let prefixExpr = arena.appendTemporary(type: stringType)
        body.append(.constValue(result: prefixExpr, value: .stringLiteral(interner.intern("\(ownerName)("))))
        let builderExpr = arena.appendTemporary(type: sema.types.anyType)
        body.append(.call(
            callee: interner.intern("__kk_string_builder_new_from_string_flat"),
            arguments: [prefixExpr],
            result: builderExpr,
            canThrow: false
        ))

        for (index, propID) in properties.enumerated() {
            let propName = sema.symbols.symbol(propID).map { interner.resolve($0.name) } ?? "prop\(index)"
            let labelText: String
            if index == 0 {
                labelText = includeFieldNames ? "\(propName)=" : ""
            } else {
                labelText = includeFieldNames ? ", \(propName)=" : ", "
            }
            if !labelText.isEmpty {
                let labelExpr = arena.appendTemporary(type: stringType)
                body.append(.constValue(result: labelExpr, value: .stringLiteral(interner.intern(labelText))))
                body.append(.call(
                    callee: interner.intern("__kk_string_builder_append_obj"),
                    arguments: [builderExpr, labelExpr],
                    result: builderExpr,
                    canThrow: false
                ))
            }

            let propType = sema.symbols.propertyType(for: propID) ?? sema.types.anyType
            let propVal = arena.appendTemporary(type: propType)
            if let offset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propID, sema: sema) {
                let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: sema.types.intType)
                body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))
                body.append(.call(
                    callee: interner.intern("kk_array_get_inbounds"),
                    arguments: [selfRef, offsetExpr],
                    result: propVal,
                    canThrow: false
                ))
            } else {
                body.append(.constValue(result: propVal, value: .null))
            }

            let propStr = callLowerer.emitAnyToStringWithNullGuard(
                valueID: propVal,
                valueType: propType,
                sema: sema,
                arena: arena,
                interner: interner,
                instructions: &body
            )
            body.append(.call(
                callee: interner.intern("__kk_string_builder_append_obj"),
                arguments: [builderExpr, propStr],
                result: builderExpr,
                canThrow: false
            ))
        }

        let suffixExpr = arena.appendTemporary(type: stringType)
        body.append(.constValue(result: suffixExpr, value: .stringLiteral(interner.intern(")"))))
        body.append(.call(
            callee: interner.intern("__kk_string_builder_append_obj"),
            arguments: [builderExpr, suffixExpr],
            result: builderExpr,
            canThrow: false
        ))
        let resultExpr = arena.appendTemporary(type: stringType)
        body.append(.call(
            callee: interner.intern("__kk_string_builder_toString"),
            arguments: [builderExpr],
            result: resultExpr,
            canThrow: false
        ))
        body.append(.returnValue(resultExpr))

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: [KIRParameter(symbol: selfParam, type: receiverType)],
            returnType: stringType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokEquals(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        properties: [SymbolID],
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let boolType = sema.types.booleanType
        let receiverType = signature.receiverType ?? sema.types.anyType
        let otherType = signature.parameterTypes.first ?? sema.types.nullableAnyType

        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let otherParam = signature.valueParameterSymbols.first ?? makeLombokReceiverParam(
            ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [],
            paramName: "other",
            shared: shared
        )
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)
        let otherRef = arena.appendExpr(.symbolRef(otherParam), type: otherType)

        let trueLabel = ctx.makeLoopLabel()
        let falseLabel = ctx.makeLoopLabel()
        let checkTypeLabel = ctx.makeLoopLabel()

        let zeroExpr = arena.appendExpr(.boolLiteral(false), type: boolType)
        let trueExpr = arena.appendExpr(.boolLiteral(true), type: boolType)
        let falseExpr = arena.appendExpr(.boolLiteral(false), type: boolType)

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
            .constValue(result: otherRef, value: .symbolRef(otherParam)),
            .constValue(result: zeroExpr, value: .boolLiteral(false)),
            .constValue(result: trueExpr, value: .boolLiteral(true)),
            .constValue(result: falseExpr, value: .boolLiteral(false)),
            .jumpIfEqual(lhs: selfRef, rhs: otherRef, target: trueLabel),
            .jumpIfNotNull(value: otherRef, target: checkTypeLabel),
            .jump(falseLabel),
            .label(checkTypeLabel),
        ]

        let typeToken = exprLowerer.lowerTypeCheckTokenExpr(
            targetType: receiverType,
            sema: sema,
            interner: interner,
            arena: arena,
            instructions: &body
        )
        let isSameType = arena.appendTemporary(type: boolType)
        body.append(.call(
            callee: interner.intern("kk_op_is"),
            arguments: [otherRef, typeToken],
            result: isSameType,
            canThrow: false
        ))
        body.append(.jumpIfEqual(lhs: isSameType, rhs: zeroExpr, target: falseLabel))

        for propID in properties {
            guard let offset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propID, sema: sema) else {
                continue
            }
            let propType = sema.symbols.propertyType(for: propID) ?? sema.types.anyType
            let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: sema.types.intType)
            body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))

            let lhsVal = arena.appendTemporary(type: propType)
            let rhsVal = arena.appendTemporary(type: propType)
            body.append(.call(
                callee: interner.intern("kk_array_get_inbounds"),
                arguments: [selfRef, offsetExpr],
                result: lhsVal,
                canThrow: false
            ))
            body.append(.call(
                callee: interner.intern("kk_array_get_inbounds"),
                arguments: [otherRef, offsetExpr],
                result: rhsVal,
                canThrow: false
            ))
            let boxedLhs = boxSentinelProneValueForAnyDispatch(
                lhsVal,
                sourceType: propType,
                sema: sema,
                interner: interner,
                arena: arena,
                into: &body
            )
            let boxedRhs = boxSentinelProneValueForAnyDispatch(
                rhsVal,
                sourceType: propType,
                sema: sema,
                interner: interner,
                arena: arena,
                into: &body
            )
            let eqExpr = arena.appendTemporary(type: boolType)
            body.append(.call(
                callee: interner.intern("kk_op_eq"),
                arguments: [boxedLhs, boxedRhs],
                result: eqExpr,
                canThrow: false
            ))
            body.append(.jumpIfEqual(lhs: eqExpr, rhs: zeroExpr, target: falseLabel))
        }

        body.append(.label(trueLabel))
        body.append(.returnValue(trueExpr))
        body.append(.label(falseLabel))
        body.append(.returnValue(falseExpr))

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: [
                KIRParameter(symbol: selfParam, type: receiverType),
                KIRParameter(symbol: otherParam, type: otherType),
            ],
            returnType: boolType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokHashCode(
        methodSymbol: SymbolID,
        name: InternedString,
        ownerClass: SymbolID,
        properties: [SymbolID],
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let intType = sema.types.intType
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]

        var accExpr: KIRExprID?
        for propID in properties {
            guard let offset = resolveFieldOffset(ownerClass: ownerClass, propertySymbol: propID, sema: sema) else {
                continue
            }
            let propType = sema.symbols.propertyType(for: propID) ?? sema.types.anyType
            let offsetExpr = arena.appendExpr(.intLiteral(Int64(offset)), type: intType)
            body.append(.constValue(result: offsetExpr, value: .intLiteral(Int64(offset))))
            let propVal = arena.appendTemporary(type: propType)
            body.append(.call(
                callee: interner.intern("kk_array_get_inbounds"),
                arguments: [selfRef, offsetExpr],
                result: propVal,
                canThrow: false
            ))
            let boxedProp = boxSentinelProneValueForAnyDispatch(
                propVal,
                sourceType: propType,
                sema: sema,
                interner: interner,
                arena: arena,
                into: &body
            )
            let tagExpr = arena.appendExpr(.intLiteral(computeAnyFallbackTag(for: propType, sema: sema)), type: intType)
            body.append(.constValue(result: tagExpr, value: .intLiteral(computeAnyFallbackTag(for: propType, sema: sema))))
            let propHash = arena.appendTemporary(type: intType)
            body.append(.call(
                callee: interner.intern("kk_any_hashCode"),
                arguments: [boxedProp, tagExpr],
                result: propHash,
                canThrow: false
            ))
            if let currentAcc = accExpr {
                let factorExpr = arena.appendExpr(.intLiteral(31), type: intType)
                body.append(.constValue(result: factorExpr, value: .intLiteral(31)))
                let scaledExpr = arena.appendTemporary(type: intType)
                body.append(.call(
                    callee: interner.intern("kk_op_mul"),
                    arguments: [currentAcc, factorExpr],
                    result: scaledExpr,
                    canThrow: false
                ))
                let combinedExpr = arena.appendTemporary(type: intType)
                body.append(.call(
                    callee: interner.intern("kk_op_add"),
                    arguments: [scaledExpr, propHash],
                    result: combinedExpr,
                    canThrow: false
                ))
                accExpr = combinedExpr
            } else {
                accExpr = propHash
            }
        }

        if let accExpr {
            body.append(.returnValue(accExpr))
        } else {
            let zeroExpr = arena.appendExpr(.intLiteral(0), type: intType)
            body.append(.constValue(result: zeroExpr, value: .intLiteral(0)))
            body.append(.returnValue(zeroExpr))
        }

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: [KIRParameter(symbol: selfParam, type: receiverType)],
            returnType: intType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokFactoryCall(
        methodSymbol: SymbolID,
        name: InternedString,
        targetClass: SymbolID,
        constructorSymbol: SymbolID,
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        var params = [KIRParameter(symbol: selfParam, type: receiverType)]
        for (idx, paramType) in signature.parameterTypes.enumerated() {
            let pSym = signature.valueParameterSymbols.indices.contains(idx)
                ? signature.valueParameterSymbols[idx]
                : methodSymbol
            params.append(KIRParameter(symbol: pSym, type: paramType))
        }

        var body: [KIRInstruction] = []
        let allocatedObj = emitAllocateLombokInstance(
            ownerSymbol: targetClass,
            resultType: signature.returnType,
            sema: sema,
            arena: arena,
            interner: interner,
            instructions: &body
        )

        var ctorArgs: [KIRExprID] = [allocatedObj]
        for param in params.dropFirst() {
            let argRef = arena.appendExpr(.symbolRef(param.symbol), type: param.type)
            body.append(.constValue(result: argRef, value: .symbolRef(param.symbol)))
            ctorArgs.append(argRef)
        }
        let ctorResult = arena.appendTemporary(type: signature.returnType)
        body.append(.call(
            symbol: constructorSymbol,
            callee: interner.intern("<init>"),
            arguments: ctorArgs,
            result: ctorResult,
            canThrow: false
        ))
        body.append(.returnValue(allocatedObj))

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: params,
            returnType: signature.returnType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    private func emitLombokBuilderBuild(
        methodSymbol: SymbolID,
        name: InternedString,
        targetClass: SymbolID,
        builderClass: SymbolID,
        fieldPairs: [(builderProp: SymbolID, targetProp: SymbolID)],
        signature: FunctionSignature,
        shared: KIRLoweringSharedContext
    ) -> KIRDeclID? {
        let sema = shared.sema
        let arena = shared.arena
        let interner = shared.interner
        let receiverType = signature.receiverType ?? sema.types.anyType
        let selfParam = makeLombokReceiverParam(ownerFQName: sema.symbols.symbol(methodSymbol)?.fqName ?? [], shared: shared)
        let selfRef = arena.appendExpr(.symbolRef(selfParam), type: receiverType)

        var body: [KIRInstruction] = [
            .constValue(result: selfRef, value: .symbolRef(selfParam)),
        ]
        let targetObj = emitAllocateLombokInstance(
            ownerSymbol: targetClass,
            resultType: signature.returnType,
            sema: sema,
            arena: arena,
            interner: interner,
            instructions: &body
        )

        for pair in fieldPairs {
            guard let builderOffset = resolveFieldOffset(ownerClass: builderClass, propertySymbol: pair.builderProp, sema: sema),
                  let targetOffset = resolveFieldOffset(ownerClass: targetClass, propertySymbol: pair.targetProp, sema: sema)
            else { continue }
            let propType = sema.symbols.propertyType(for: pair.targetProp) ?? sema.types.anyType
            let bOffsetExpr = arena.appendExpr(.intLiteral(Int64(builderOffset)), type: sema.types.intType)
            body.append(.constValue(result: bOffsetExpr, value: .intLiteral(Int64(builderOffset))))
            let loaded = arena.appendTemporary(type: propType)
            body.append(.call(
                callee: interner.intern("kk_array_get_inbounds"),
                arguments: [selfRef, bOffsetExpr],
                result: loaded,
                canThrow: false
            ))
            let tOffsetExpr = arena.appendExpr(.intLiteral(Int64(targetOffset)), type: sema.types.intType)
            body.append(.constValue(result: tOffsetExpr, value: .intLiteral(Int64(targetOffset))))
            let setRes = arena.appendTemporary(type: sema.types.anyType)
            body.append(.call(
                callee: interner.intern("kk_array_set"),
                arguments: [targetObj, tOffsetExpr, loaded],
                result: setRes,
                canThrow: false
            ))
        }

        body.append(.returnValue(targetObj))

        let kirFunc = KIRFunction(
            symbol: methodSymbol,
            name: name,
            params: [KIRParameter(symbol: selfParam, type: receiverType)],
            returnType: signature.returnType,
            body: body,
            isSuspend: false,
            isInline: false
        )
        return arena.appendDecl(.function(kirFunc))
    }

    // MARK: - Helpers

    private func resolveFieldOffset(
        ownerClass: SymbolID,
        propertySymbol: SymbolID,
        sema: SemaModule
    ) -> Int? {
        resolvePluginPropertyOffset(ownerClass: ownerClass, propertySymbol: propertySymbol, sema: sema)
    }

    private func makeLombokReceiverParam(
        ownerFQName: [InternedString],
        paramName: String = "$self",
        shared: KIRLoweringSharedContext
    ) -> SymbolID {
        makePluginSyntheticParam(ownerFQName: ownerFQName, paramName: paramName, shared: shared)
    }

    private func emitAllocateLombokInstance(
        ownerSymbol: SymbolID,
        resultType: TypeID,
        sema: SemaModule,
        arena: KIRArena,
        interner: StringInterner,
        instructions: inout [KIRInstruction]
    ) -> KIRExprID {
        emitAllocatePluginNominalInstance(
            ownerSymbol: ownerSymbol,
            resultType: resultType,
            sema: sema,
            arena: arena,
            interner: interner,
            instructions: &instructions
        )
    }
}
